SRC_xle            as ( SELECT LEGAL_ENTITY_ID, LEGAL_ENTITY_IDENTIFIER FROM {{ source('outd_ocf_xle', 'xle_entity_profiles') }} as SRC 
                        qualify 1= row_number()over(partition by legal_entity_id order by _fivetran_synced desc, psa_load_dts desc) )

