, RENAME_a as (
    SELECT
        REC_SRC
      , BKCC
    FROM LOGIC_a
)

, RENAME_sup as (
    SELECT
        SUP_VENDOR_ID
      , SUP_SEGMENT1
    FROM LOGIC_sup
)

, RENAME_pofib as (
    SELECT
        POFIB_PO_HEADER_ID
      , VENDOR_ID
      , SOLDTO_LE_ID
    FROM LOGIC_pofib
)

, RENAME_itm as (
    SELECT
        INVENTORY_ITEM_ID
      , ITM_ITEM_NUMBER
    FROM LOGIC_itm
)

, RENAME_xle as (
    SELECT
        LEGAL_ENTITY_ID
      , LEGAL_ENTITY_IDENTIFIER
    FROM LOGIC_xle
)
---- FILTER LAYER ----

, FILTER_polfib as (
    SELECT *
    FROM RENAME_polfib
)

, FILTER_pofib as (
    SELECT *
    FROM RENAME_pofib
)

, FILTER_a as (
    SELECT *
    FROM RENAME_a
    WHERE rec_src = 'USCLOUD.ORCL.OCFPRD.PO_LINES_ALL'
)

, FILTER_sup as (
    SELECT *
    FROM RENAME_sup
)

, FILTER_itm as (
    SELECT *
    FROM RENAME_itm
)

, FILTER_xle as (
    SELECT *
    FROM RENAME_xle
)

---- JOIN LAYER ----
, JOIN_RESULT as (
    SELECT *
    FROM FILTER_polfib
    LEFT JOIN FILTER_pofib
        ON FILTER_polfib.PO_HEADER_ID = FILTER_pofib.POFIB_PO_HEADER_ID
    INNER JOIN FILTER_a
        ON '1' = '1'
    LEFT JOIN FILTER_itm
        ON FILTER_polfib.ITEM_ID = FILTER_itm.INVENTORY_ITEM_ID 
    LEFT JOIN FILTER_sup
        ON FILTER_pofib.VENDOR_ID = FILTER_sup.sup_vendor_id
    LEFT JOIN FILTER_xle
        ON FILTER_pofib.SOLDTO_LE_ID = FILTER_xle.LEGAL_ENTITY_ID
)

---- FINAL LAYER ----
